CREATE TABLE IF NOT EXISTS threads(id TEXT PRIMARY KEY,title TEXT NOT NULL,created_at INTEGER NOT NULL,last_activity INTEGER NOT NULL,deleted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,number INTEGER NOT NULL,author TEXT NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL,deleted INTEGER DEFAULT 0,UNIQUE(thread_id,number));
CREATE INDEX IF NOT EXISTS posts_thread ON posts(thread_id,number);
CREATE INDEX IF NOT EXISTS threads_active ON threads(deleted,last_activity DESC);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL);